INSERT INTO zinas (virsraksts, teksts, kategorija, izveidots, publicets) VALUES
('Ziema klusi pienāk',
'Oktobris tuvojas beigām, un aiz loga klusi līst lietus. Ceļojums uz Latviju palika gaišā atmiņā — pludmale atkal bija tā īstā lieta, un, protams, Mežupes.\n\nTagad, kad mēnesis mainās uz novembri, vakari kļūst arvien tumšāki un temperatūra krītas. Sals lēnām pielavās un ar savu miglaino tvērienu sāk mūs turēt savā varā nākamos sešus mēnešus.\n\nTaču nav no kā baidīties. Risinājums ir vienkāršs: pieliec malku kamīnā, uzkurini plīts liesmu un kļūsti kluss. Un neaizmirsti aiziet uz jogu.\n\nNamaste.\n\n⸻\n\nLokakuu on lopuillaan, ja ulkona ropisee hiljainen vesisade. Latvian matka jäi hyvänä mieleen — ranta oli jälleen kerran se juttu, ja tietenkin Mežupes.\n\nNyt kun kuukausi vaihtuu marraskuuksi, illat pimenevät entisestään ja lämpötila laskee. Pakkanen hiipii vähitellen ja alkaa huuruisella otteellaan pitää meitä hallussaan seuraavat puoli vuotta.\n\nMutta siinä ei ole mitään pelättävää. Ratkaisu on yksinkertainen: lisää puita takkaan, kohenna hellan liekkiä ja hiljenny. Ja muista käydä joogassa.\n\nNamaste.',
'zina',
'2026-10-29 08:00:00',
1);
